import{_ as e,o as r,c as i,a2 as o}from"./chunks/framework.DN6PggGS.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"interview/distributed/microservice.md","filePath":"interview/distributed/microservice.md"}'),l={name:"interview/distributed/microservice.md"};function t(n,a,s,c,h,u){return r(),i("div",null,[...a[0]||(a[0]=[o('<h2 id="微服务" tabindex="-1">微服务 <a class="header-anchor" href="#微服务" aria-label="Permalink to &quot;微服务&quot;">​</a></h2><h3 id="谈谈你对微服务的理解-微服务有哪些优缺点" tabindex="-1">谈谈你对微服务的理解，微服务有哪些优缺点？ <a class="header-anchor" href="#谈谈你对微服务的理解-微服务有哪些优缺点" aria-label="Permalink to &quot;谈谈你对微服务的理解，微服务有哪些优缺点？&quot;">​</a></h3><p>微服务是由Martin Flowler大师提出的。微服务是一种架构风格，通过将大型的单体应用划分为比较小的服务单元，从而降低整个系统的复杂度。</p><p>具有以下优点：</p><ul><li>服务部署更灵活：每个应用都可以是一个独立的项目，可以独立部署，不依赖其他服务，耦合性降低。</li><li>技术选型更加灵活，在大型大体应用中，技术要进行更新，往往是非常困难的。而微服务可以根据业务特点，灵活选择技术栈。</li><li>应用的性能得到提高，大型单体应用中，往往启动就会成为一个很大的难关，而采用微服务之后，整个系统的性能是能够提高的。</li><li>更容易组合专门的团队，在单体应用中，团队成员往往需要对系统的各个部分都要有深入的了解，门槛是很高的。而采用微服务之后，可以给每个微服务组件专门的团队</li><li>代码复用：很多底层服务可以以REST API的方式对外提供统一的服务，所有基础服务可以在整个微服务系统中调用。</li></ul><p>对应的有以下缺点：</p><ul><li>服务调用的复杂性提高了，面临网络问题、容错问题、负载问题、高并发等等问题</li><li>分布式事务，尽量不要使用微服务的分布式事务</li><li>测试的难度提升了</li><li>运维的难度提升了，单体架构只要维护一个环节，而到了微服务是很多个环境，并且运维方式还都不一样。所以对部署、监控、告警等要求就会变得非常困难</li></ul><h3 id="springcloud和springcloudalibaba有哪些组件-都解决了什么问题" tabindex="-1">SpringCloud和SpringCloudAlibaba有哪些组件？都解决了什么问题？ <a class="header-anchor" href="#springcloud和springcloudalibaba有哪些组件-都解决了什么问题" aria-label="Permalink to &quot;SpringCloud和SpringCloudAlibaba有哪些组件？都解决了什么问题？&quot;">​</a></h3><p>SpringCloud是提供了构建微服务系统所需要的一组通用开发模式以及一系列快速实现这些开发模式的工具。通常所说的SpringCloud是指SpringCloud NetFlix，它和SpringCloudAlibaba都是SpringCloud这一系列开发模式的具体实现。</p><p>SpringCloud NetFlix架构图：</p><img src="https://raw.githubusercontent.com/yidongnan/spring-cloud-netflix-example/master/screenshots/Architecture.png" style="zoom:67%;"><p>SpringCloudAlibaba架构图：</p><img src="https://blog-1304855543.cos.ap-guangzhou.myqcloud.com/blog/img202206142320702.png" alt="image-20220614232037661" style="zoom:50%;"><h3 id="springcloud和dubbo的区别" tabindex="-1">SpringCloud和Dubbo的区别？ <a class="header-anchor" href="#springcloud和dubbo的区别" aria-label="Permalink to &quot;SpringCloud和Dubbo的区别？&quot;">​</a></h3><p>SpringCloud使用基于HTTP的REST方式，而Dubbo采用RPC通信。这两种方式各有优劣，前者牺牲了服务调用的性能，但也能避免原生RPC带来的问题，不存在代码级别的强依赖。</p><h3 id="分布式事务如何处理-怎么保证事务一致性" tabindex="-1">分布式事务如何处理？怎么保证事务一致性？ <a class="header-anchor" href="#分布式事务如何处理-怎么保证事务一致性" aria-label="Permalink to &quot;分布式事务如何处理？怎么保证事务一致性？&quot;">​</a></h3><p>详细参见：<a href="https://juejin.cn/post/7116916308825866254" target="_blank" rel="noreferrer">深入浅出分布式事务的实现原理</a>。</p><h3 id="怎么拆分微服务-怎样设计出高内聚、低耦合的微服务" tabindex="-1">怎么拆分微服务？怎样设计出高内聚、低耦合的微服务？ <a class="header-anchor" href="#怎么拆分微服务-怎样设计出高内聚、低耦合的微服务" aria-label="Permalink to &quot;怎么拆分微服务？怎样设计出高内聚、低耦合的微服务？&quot;">​</a></h3><p>拆分微服务的时候，为了保证微服务的稳定，会有一些基本的准则：</p><ul><li>微服务之间尽量不要有业务交叉。</li><li>微服务之间只能通过接口进行服务调用，而不能绕过接口直接访问对方的数据</li><li>高内聚，低耦合。</li></ul><blockquote><p>高内聚低耦合，是一种从上而下指导微服务设计的方法。·实现高内聚低耦合的工具主要有同步的接口调用和异步的事件驱动（MQ）两种方式。</p></blockquote><h3 id="有没有了解通过ddd领域驱动设计" tabindex="-1">有没有了解通过DDD领域驱动设计？ <a class="header-anchor" href="#有没有了解通过ddd领域驱动设计" aria-label="Permalink to &quot;有没有了解通过DDD领域驱动设计？&quot;">​</a></h3><p>什么是DDD：在2004年，由Eric Evans提出的，DDD是面对软件复杂之道。Domain-Driven-Design</p><p>Martin Flowler - 贫血模型 - 贫血失忆症 充血模型</p><p>MVC架构 -&gt; 领域优先的四层架构</p><img src="https://blog-1304855543.cos.ap-guangzhou.myqcloud.com/blog/img/20210630002318.png" alt="img" style="zoom:67%;"><p>大泥团：不利于微服务的拆分，大泥团结构拆分出来的微服务就是泥团结构，当服务业务逐渐复杂，这个泥团又会膨胀成为大泥团。</p><p>DDD只是一种方法论，没有一个稳定的技术框架。DDD要求领域是跟技术无关、跟存储无关、跟通信无关。</p><h3 id="微服务的链路追踪、持续集成、ab发布要怎么做" tabindex="-1">微服务的链路追踪、持续集成、AB发布要怎么做？ <a class="header-anchor" href="#微服务的链路追踪、持续集成、ab发布要怎么做" aria-label="Permalink to &quot;微服务的链路追踪、持续集成、AB发布要怎么做？&quot;">​</a></h3><p>链路追踪：</p><ul><li>基于日志，形成全局事务ID，落地到日志文件。filebeat -logstash- Elaticsearch形成大型报表</li><li>基于MQ，往往需要架构支持，经过流式计算形成一些可视化的结果</li></ul><p>持续集成：通过jenkins自动化构建任务</p><p>AB发布：</p><ul><li>AB发布又称蓝绿发布：红黑发布。老版本和新版本是同时存在的</li><li>灰度发布：金丝雀发布</li></ul><h3 id="nacos和eureka的区别" tabindex="-1">Nacos和Eureka的区别？ <a class="header-anchor" href="#nacos和eureka的区别" aria-label="Permalink to &quot;Nacos和Eureka的区别？&quot;">​</a></h3><ul><li>Nacos提供了服务的注册与发现，同时也提供了配置中心，而Eureka只提供了服务注册与发现</li><li>Nacos本身支持负载均衡，而Eureka不支持</li><li>Nacos同时支持AP和CP模式，而Eureka只满足AP模式</li></ul><div class="note info"><p>CAP原则又称为CAP定理，指的是在一个分布式系统中，Consistency（一致性），Availability（可用性）、Partition tolerance（分区容错性），三者不可得兼。</p></div><h3 id="nacos配置中心-本地resource-jar包中同级目录的配置文件加载优先级" tabindex="-1">Nacos配置中心，本地Resource，jar包中同级目录的配置文件加载优先级？ <a class="header-anchor" href="#nacos配置中心-本地resource-jar包中同级目录的配置文件加载优先级" aria-label="Permalink to &quot;Nacos配置中心，本地Resource，jar包中同级目录的配置文件加载优先级？&quot;">​</a></h3><h3 id="nacos的配置动态更新原理" tabindex="-1">Nacos的配置动态更新原理？ <a class="header-anchor" href="#nacos的配置动态更新原理" aria-label="Permalink to &quot;Nacos的配置动态更新原理？&quot;">​</a></h3><p><a href="https://juejin.cn/s/nacos%E9%85%8D%E7%BD%AE%E5%8A%A8%E6%80%81%E6%9B%B4%E6%96%B0%E5%8E%9F%E7%90%86" target="_blank" rel="noreferrer">nacos配置动态更新原理</a></p><h3 id="使用nacos配置中心-value对应的配置项如何动态更新" tabindex="-1">使用Nacos配置中心，@Value对应的配置项如何动态更新？ <a class="header-anchor" href="#使用nacos配置中心-value对应的配置项如何动态更新" aria-label="Permalink to &quot;使用Nacos配置中心，@Value对应的配置项如何动态更新？&quot;">​</a></h3><h3 id="nacos中命名空间和分组的概念及区别" tabindex="-1">Nacos中命名空间和分组的概念及区别？ <a class="header-anchor" href="#nacos中命名空间和分组的概念及区别" aria-label="Permalink to &quot;Nacos中命名空间和分组的概念及区别？&quot;">​</a></h3><h3 id="nacos同一个namespace中的不同的group注册的服务可以相互访问吗" tabindex="-1">Nacos同一个namespace中的不同的group注册的服务可以相互访问吗？ <a class="header-anchor" href="#nacos同一个namespace中的不同的group注册的服务可以相互访问吗" aria-label="Permalink to &quot;Nacos同一个namespace中的不同的group注册的服务可以相互访问吗？&quot;">​</a></h3><h3 id="nacos服务注册的流程是怎么样的" tabindex="-1">Nacos服务注册的流程是怎么样的？ <a class="header-anchor" href="#nacos服务注册的流程是怎么样的" aria-label="Permalink to &quot;Nacos服务注册的流程是怎么样的？&quot;">​</a></h3><h3 id="微服务下服务a调用服务b的流程" tabindex="-1">微服务下服务a调用服务b的流程？ <a class="header-anchor" href="#微服务下服务a调用服务b的流程" aria-label="Permalink to &quot;微服务下服务a调用服务b的流程？&quot;">​</a></h3><h3 id="注册中心-如何通过服务名找到服务实例" tabindex="-1">注册中心，如何通过服务名找到服务实例？ <a class="header-anchor" href="#注册中心-如何通过服务名找到服务实例" aria-label="Permalink to &quot;注册中心，如何通过服务名找到服务实例？&quot;">​</a></h3><h3 id="熔断和限流有什么区别" tabindex="-1">熔断和限流有什么区别？ <a class="header-anchor" href="#熔断和限流有什么区别" aria-label="Permalink to &quot;熔断和限流有什么区别？&quot;">​</a></h3><p><a href="https://zhuanlan.zhihu.com/p/61363959" target="_blank" rel="noreferrer">降级-熔断-限流</a></p><h3 id="雪花算法有什么缺点" tabindex="-1">雪花算法有什么缺点？ <a class="header-anchor" href="#雪花算法有什么缺点" aria-label="Permalink to &quot;雪花算法有什么缺点？&quot;">​</a></h3><h3 id="gateway有哪些功能-如何配置动态路由" tabindex="-1">Gateway有哪些功能？如何配置动态路由？ <a class="header-anchor" href="#gateway有哪些功能-如何配置动态路由" aria-label="Permalink to &quot;Gateway有哪些功能？如何配置动态路由？&quot;">​</a></h3><h3 id="如何手写一个注册中心" tabindex="-1">如何手写一个注册中心？ <a class="header-anchor" href="#如何手写一个注册中心" aria-label="Permalink to &quot;如何手写一个注册中心？&quot;">​</a></h3>',51)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
